code.cpp:
class Solution {
public:
    vector<int> minBitwiseArray(vector<int>& nums) {
        int n = nums.size();
        vector<int> ans(n);
        for (int i = 0; i < n; i++) {
            if (nums[i] % 2 == 0) {
                ans[i] = -1;
            } else {
                int lowestZero = (nums[i] + 1) & (-(nums[i] + 1));
                ans[i] = nums[i] ^ (lowestZero >> 1);
            }
        }
        return ans;
    }
};
